  'WXT_ENV_TEST_EXPANDED',
] as const;

describe('loadEnv', () => {
  beforeEach(() => {
    TEST_ENV_KEYS.forEach((key) => delete process.env[key]);
  });

  afterEach(() => {
    TEST_ENV_KEYS.forEach((key) => delete process.env[key]);
  });

  it('loads and expands dotenv files into process.env', () => {
    const files: Record<string, string> = {
      '.env': [
        'WXT_ENV_TEST_VALUE=base',
        'WXT_ENV_TEST_EXPANDED=${WXT_ENV_TEST_VALUE}-expanded',
      ].join('\n'),
      '.env.production.chrome': 'WXT_ENV_TEST_VALUE=specific',
    };
    vi.mocked(existsSync).mockImplementation((path) => String(path) in files);
    vi.mocked(readFileSync).mockImplementation((path) => files[String(path)]);

    loadEnv('production', 'chrome');

    expect(process.env.WXT_ENV_TEST_VALUE).toBe('specific');
    expect(process.env.WXT_ENV_TEST_EXPANDED).toBe('specific-expanded');
  });

  it('does not overwrite values from the parent process', () => {
    process.env.WXT_ENV_TEST_VALUE = 'parent';
    vi.mocked(existsSync).mockReturnValue(true);
    vi.mocked(readFileSync).mockReturnValue(
      'WXT_ENV_TEST_VALUE=dotenv\nWXT_ENV_TEST_EXPANDED=${WXT_ENV_TEST_VALUE}-expanded',
    );

    loadEnv('production', 'chrome');

    expect(process.env.WXT_ENV_TEST_VALUE).toBe('parent');
    expect(process.env.WXT_ENV_TEST_EXPANDED).toBe('parent-expanded');
  });
});
